TOPICS = [
{'slug':'unterhaltsreinigung','name':'Unterhaltsreinigung','claim':'Sauberkeit hat einen Rhythmus.','image':'service-0.webp','alt':'COMPAKT Mitarbeiter wischt den Holzboden eines Veranstaltungsraums','ai':False,'intro':'Regelmäßige Reinigung für Arbeitsräume, Gemeinschaftsflächen und Sanitärbereiche in Fürstenwalde/Spree und der Region. COMPAKT stimmt Aufgaben und Intervalle auf die Nutzung Ihrer Immobilie ab.','sections':[
('Was gehört zur Unterhaltsreinigung?','Unterhaltsreinigung bezeichnet die wiederkehrende Pflege eines Gebäudes. Dazu können das Reinigen von Böden, das Entfernen von Staub auf zugänglichen Oberflächen, die Pflege von Sanitärbereichen und das Leeren von Abfallbehältern gehören. Entscheidend ist das vereinbarte Leistungsverzeichnis: Es hält fest, welche Räume und Aufgaben zum Auftrag zählen. Fenster, Polster oder eine intensive Grundreinigung sollten gesondert aufgeführt werden, damit keine unterschiedlichen Erwartungen entstehen.'),
('Täglich, wöchentlich oder nach Bedarf?','Ein pauschaler Turnus passt selten zu allen Räumen. Eingänge mit viel Publikumsverkehr benötigen eine andere Aufmerksamkeit als gelegentlich genutzte Besprechungsräume. Mitarbeitendenzahl, Bodenbeläge, Schmutzeintrag und Nutzungszeiten geben die Richtung vor. Gemeinsam betrachten wir diese Bereiche und legen eine sinnvolle Aufteilung fest. Bei saisonalen Veränderungen, etwa mehr Nässe und Laub im Eingangsbereich, kann der Plan nach Absprache angepasst werden.'),
('Reinigung im laufenden Betrieb organisieren','Damit die Arbeit in Ihrem Gebäude weiterlaufen kann, klären wir Zeitfenster, Zugang und die Bereitstellung von Wasser und Strom. Auch verschlossene Räume, sensible Arbeitsbereiche oder Alarmanlagen müssen vor dem ersten Einsatz besprochen werden. Ein vereinbarter Kontakt auf beiden Seiten erleichtert Rückfragen. Wenn Bereiche an einzelnen Tagen nicht zugänglich sind, lässt sich das frühzeitig in der Planung berücksichtigen.'),
('Leistungen nachvollziehbar vereinbaren','Ein guter Reinigungsplan beschreibt Räume, Tätigkeiten und Häufigkeiten verständlich. Bei der Abstimmung trennen wir regelmäßig beauftragte Aufgaben von Zusatzarbeiten. Hinweise zu empfindlichen Materialien oder vorhandenen Schäden helfen, geeignete Verfahren auszuwählen. Rückmeldungen zur Ausführung können gezielt einem Bereich zugeordnet werden. So entsteht eine verlässliche Grundlage für die laufende Betreuung und spätere Änderungen.'),
('Diese Informationen helfen bei Ihrem Angebot','Nennen Sie uns die Adresse, die ungefähre Fläche, die Raumarten und den gewünschten Beginn. Ein Grundriss oder vorhandenes Leistungsverzeichnis unterstützt die Vorbereitung. Teilen Sie uns außerdem mit, ob die Reinigung während oder außerhalb Ihrer Nutzungszeiten stattfinden soll. Auf dieser Grundlage klären wir offene Punkte und stimmen bei Bedarf eine Besichtigung ab. Die Kosten richten sich nach dem tatsächlichen Umfang und den Bedingungen im Objekt.')],
'faq':[('Ist Unterhaltsreinigung dasselbe wie Grundreinigung?','Nein. Unterhaltsreinigung erfolgt regelmäßig. Eine Grundreinigung ist eine intensivere, gesondert geplante Reinigung, die je nach Boden und Verschmutzung ergänzend sinnvoll sein kann.'),('Sind Reinigungsmittel und Geräte enthalten?','Welche Geräte und Materialien gestellt werden und wo sie gelagert werden können, wird im Angebot beziehungsweise in der Leistungsvereinbarung festgehalten.')],
'related':['bueroreinigung','treppenhausreinigung','glasreinigung']},
{'slug':'bueroreinigung','name':'Büroreinigung','claim':'Ein guter Arbeitstag beginnt im Raum.','image':'archive-glasreinigung-vom-profi-fuer-den-klaren-durchblick.webp','alt':'Reinigung einer großen Fensterfläche in einem Innenraum','ai':True,'intro':'Gepflegte Arbeitsplätze, einladende Besprechungsräume und saubere Gemeinschaftsbereiche: COMPAKT plant Ihre Büroreinigung in Fürstenwalde und Umgebung passend zu Ihrem Betrieb.','sections':[
('Arbeitsbereiche sinnvoll aufteilen','In einem Büro treffen unterschiedliche Nutzungen aufeinander. Empfang und Besprechungsräume prägen den Eindruck bei Gästen, während Teeküchen und Sanitärbereiche täglich von vielen Personen genutzt werden. Arbeitsplätze benötigen wiederum eine klare Abstimmung zu freien Oberflächen und persönlichen Gegenständen. Wir besprechen, welche Bereiche betreut werden sollen und wie sich die Aufgaben sinnvoll in einen regelmäßigen Ablauf einfügen.'),
('Arbeitsplätze und vertrauliche Unterlagen','Nicht jede Tischfläche ist zum Reinigen freigegeben. Legen Sie deshalb vorab fest, welche Flächen frei sein müssen und welche Gegenstände nicht bewegt werden sollen. Für Unterlagen, Bildschirme, Tastaturen und andere technische Geräte sind gesonderte Absprachen sinnvoll. Die Reinigung ersetzt keine fachgerechte Wartung von Technik. Ein verständlicher Ablauf schützt Ihre Arbeitsorganisation und erleichtert den Mitarbeitenden die Vorbereitung.'),
('Teeküche, Sanitärbereiche und Besprechungsräume','Gerade gemeinschaftlich genutzte Räume brauchen nachvollziehbare Zuständigkeiten. Welche Oberflächen, Spülen und Böden zur Reinigung gehören, wird konkret vereinbart. Das Nachfüllen von Verbrauchsmaterialien, das Reinigen von Kühlschränken oder das Spülen von Geschirr sind zusätzliche Aufgaben, die ausdrücklich besprochen werden sollten. Bei Besprechungsräumen helfen Belegungszeiten, den passenden Zeitpunkt für die Reinigung zu finden.'),
('Passende Zeiten statt unnötiger Unterbrechungen','Ob früh morgens, nach Büroschluss oder in einem abgestimmten Zeitfenster: Die Möglichkeiten hängen von Ihrem Objekt und der Einsatzplanung ab. Wir klären Schlüssel, Zutritt, Alarmierung und erreichbare Ansprechpartner vor Beginn. Bei wechselnder Büroauslastung oder einer Mischung aus Präsenzarbeit und Homeoffice kann eine raumbezogene Planung helfen, den Bedarf realistisch abzubilden.'),
('Büroreinigung in Ihr Gebäudekonzept einbinden','Eine gepflegte Büroetage beginnt häufig schon am Eingang. Glasflächen, Treppenhäuser und Außenbereiche lassen sich mit der laufenden Reinigung abstimmen. Für eine Anfrage benötigen wir die Objektadresse, Fläche, Arbeitsplatzanzahl und gewünschte Häufigkeit. Nennen Sie auch besondere Materialien oder Nutzungen. COMPAKT prüft mit Ihnen eine Lösung, die zum Gebäude und zu den Abläufen Ihres Unternehmens passt.')],
'faq':[('Werden Computer und Bildschirme automatisch mitgereinigt?','Nein. Welche technischen Geräte und Oberflächen gereinigt werden dürfen und welches Verfahren geeignet ist, muss ausdrücklich abgestimmt werden.'),('Kann außerhalb der Bürozeiten gereinigt werden?','Fragen Sie Ihr gewünschtes Zeitfenster an. Wir prüfen die Einsatzmöglichkeiten und stimmen Zugang, Schlüsselregelung und Ansprechpartner mit Ihnen ab.')],
'related':['unterhaltsreinigung','glasreinigung','treppenhausreinigung']},
{'slug':'glasreinigung','name':'Glasreinigung','claim':'Freier Blick. Gepflegter Eindruck.','image':'archive-glasreinigung-vom-profi-fuer-den-klaren-durchblick.webp','alt':'Fensterreinigung mit Einwascher an einer großen Glasscheibe','ai':True,'intro':'Fenster, Glastüren und weitere zugängliche Glasflächen: COMPAKT stimmt die Glasreinigung in Fürstenwalde/Spree und der Region auf Ihr Gebäude, die Erreichbarkeit und den gewünschten Umfang ab.','sections':[
('Scheiben, Rahmen und Falze unterscheiden','Der Begriff Fensterreinigung beschreibt nicht automatisch denselben Leistungsumfang. Neben den Scheiben können Rahmen, Falze und Fensterbänke zusätzliche Arbeit erfordern. Innen- und Außenseiten unterscheiden sich oft deutlich in ihrer Verschmutzung. Deshalb legen wir vorab fest, welche Bestandteile gereinigt werden sollen. So lässt sich ein Angebot nachvollziehbar vergleichen und die spätere Ausführung eindeutig abstimmen.'),
('Erreichbarkeit ist Teil der Planung','Bodentiefe Fenster, Oberlichter und höher gelegene Glasflächen stellen unterschiedliche Anforderungen. Wichtig sind Öffnungsmöglichkeiten, Stellflächen und mögliche Hindernisse. Fotos helfen dabei, die Situation einzuordnen, ersetzen bei komplexen Gebäuden jedoch nicht immer eine Besichtigung. Notwendige Hilfsmittel und sichere Zugänge werden vor der Ausführung geklärt. Ein bestimmtes Verfahren wird erst nach Prüfung des Objekts vereinbart.'),
('Verschmutzung und Material berücksichtigen','Staub und alltägliche Spuren sind anders zu behandeln als Klebereste, Farbspritzer oder Rückstände nach Bauarbeiten. Beschichtete Scheiben und empfindliche Rahmen benötigen geeignete Verfahren. Teilen Sie bekannte Besonderheiten und Vorschäden deshalb frühzeitig mit. Das Entfernen hartnäckiger Rückstände kann als Sonderleistung geplant werden. Eine ungeprüfte Bearbeitung mit scharfen Werkzeugen ist keine geeignete pauschale Lösung.'),
('Wann ist eine Glasreinigung sinnvoll?','Der passende Rhythmus hängt unter anderem von Lage, Witterung, Verschmutzung und dem Anspruch an den Außenauftritt ab. Schaufenster und Eingangsbereiche werden häufig anders geplant als rückwärtige Fenster. Gemeinsam besprechen wir einen regelmäßigen Turnus oder einen einzelnen Termin. Für gewerblich genutzte Räume berücksichtigen wir die Betriebsabläufe und den Zugang zu den Fensterflächen.'),
('Ein Angebot für Ihre Fenster vorbereiten','Hilfreich sind die Objektadresse, eine ungefähre Anzahl und Größe der Fenster sowie Fotos. Geben Sie an, welche Seiten und Bestandteile gereinigt werden sollen und in welcher Höhe sich die Flächen befinden. Auch Park- und Zugangsmöglichkeiten sind für die Planung relevant. Auf dieser Grundlage klärt COMPAKT den Aufwand und mögliche Ergänzungen zur bestehenden Gebäudereinigung.')],
'faq':[('Sind Rahmen in der Glasreinigung enthalten?','Nur wenn dies vereinbart ist. Scheiben, Rahmen, Falze und Fensterbänke werden im Leistungsumfang ausdrücklich beschrieben.'),('Übernimmt COMPAKT auch schwer erreichbare Glasflächen?','Wir prüfen die Erreichbarkeit und geeignete Arbeitsmittel für das konkrete Objekt. Bei Bedarf werden Möglichkeiten innerhalb der FORM Gruppe abgestimmt.')],
'related':['bueroreinigung','unterhaltsreinigung','treppenhausreinigung']},
{'slug':'treppenhausreinigung','name':'Treppenhausreinigung','claim':'Der erste Eindruck wohnt im Eingang.','image':'service-7.webp','alt':'Mehrgeschossiges Wohnhaus mit begrünten Fassaden und Fenstern','ai':False,'intro':'Regelmäßige Pflege gemeinschaftlich genutzter Flächen für Eigentümer und Hausverwaltungen in Fürstenwalde und der Region. COMPAKT verbindet klare Reinigungspläne mit abgestimmten Abläufen im Haus.','sections':[
('Mehr als Stufen wischen','Zum Treppenhaus gehören häufig Podeste, Handläufe, Hauseingänge und weitere Gemeinschaftsflächen. Welche Bereiche gereinigt werden sollen, halten wir gemeinsam fest. Kellerzugänge, Aufzüge, Briefkastenanlagen und Glasflächen können gesondert berücksichtigt werden. Entscheidend sind die baulichen Gegebenheiten und Ihr Auftrag. Eine genaue Aufteilung vermeidet Unklarheiten zwischen Reinigung, Hausmeisterdienst und Aufgaben der Bewohner.'),
('Beläge und Schmutzeintrag beachten','Naturstein, Fliesen und andere Bodenbeläge benötigen jeweils passende Pflege. Im Eingangsbereich tragen Nässe, Sand und Laub zusätzlich zur Verschmutzung bei. Wir erfassen deshalb Material, Nutzung und auffällige Bereiche. Bei empfindlichen oder bereits beschädigten Oberflächen wird das Vorgehen abgestimmt. Eine regelmäßige Unterhaltsreinigung kann durch gesonderte Grundreinigung ergänzt werden, wenn der Zustand der Fläche dies nahelegt.'),
('Ein Reinigungsplan für die Hausverwaltung','Für die Verwaltung ist hilfreich, wenn Häuser, Aufgänge und Tätigkeiten eindeutig benannt sind. Ein Leistungsverzeichnis sollte auch die vorgesehenen Intervalle und den Umgang mit Zusatzaufgaben enthalten. Bei mehreren Aufgängen kann eine einheitliche Struktur die Abstimmung erleichtern. Veränderungen wie Bauarbeiten, gesperrte Bereiche oder neue Nutzungsmöglichkeiten sollten rechtzeitig mitgeteilt werden.'),
('Zugang und Bewohner im Blick behalten','Vor Beginn klären wir Schlüsselregelung, Zugang zu Wasser und Strom sowie die Erreichbarkeit der zuständigen Verwaltung. Gemeinschaftliche Verkehrswege müssen bei der Ausführung berücksichtigt werden. Persönliche Gegenstände auf Podesten oder vor Wohnungstüren sind kein automatisch vereinbarter Teil der Reinigung. Für solche Situationen hilft eine klare Absprache mit der Verwaltung, damit die Ausführung planbar bleibt.'),
('Innen- und Außenbetreuung verbinden','Ein gepflegtes Wohnobjekt endet nicht an der Haustür. Hausmeisterdienst, Grünflächenpflege und Winterdienst können mit der Treppenhausreinigung abgestimmt werden. Für Ihre Anfrage nennen Sie uns Adresse, Anzahl der Aufgänge und Etagen, Bodenbeläge und gewünschten Rhythmus. Fotos oder ein vorhandener Reinigungsplan helfen bei der Vorbereitung. Wir besprechen danach die passende Betreuung und den konkreten Leistungsumfang.')],
'faq':[('Können mehrere Häuser gemeinsam betreut werden?','Sie können mehrere Objekte mit ihren jeweiligen Adressen und Anforderungen anfragen. Wir prüfen die Organisation und stimmen ein passendes Leistungsverzeichnis ab.'),('Gehören Keller und Aufzüge automatisch dazu?','Nein. Diese Bereiche werden ausdrücklich in den Auftrag aufgenommen, wenn sie gereinigt werden sollen. Dasselbe gilt für Glasflächen und Außenbereiche.')],
'related':['unterhaltsreinigung','glasreinigung','bueroreinigung']}
]
SERVICE_DETAILS={
'gebaeudereinigung':('Reinigungsleistungen passend zur Nutzung',[('Büros & Arbeitsräume','Reinigungszeiten, frei zugängliche Oberflächen und sensible Bereiche werden so vereinbart, dass Ihre Abläufe berücksichtigt werden.'),('Wohn- & Gemeinschaftsflächen','Eingänge, Treppenhäuser und gemeinsam genutzte Räume erhalten einen nachvollziehbaren Plan mit definierten Aufgaben.'),('Grund- & Sonderreinigung','Zusätzliche Arbeiten werden nach Material, Verschmutzung und Zugang beurteilt und gesondert abgestimmt.')],[('Was beeinflusst die Kosten einer Gebäudereinigung?','Fläche, Raumarten, Verschmutzung, Häufigkeit und Zugänglichkeit bestimmen den Aufwand. Ein vorhandenes Leistungsverzeichnis und Fotos helfen bei der Einschätzung.'),('Wie unterscheiden sich Unterhalts- und Sonderreinigung?','Die Unterhaltsreinigung umfasst regelmäßig vereinbarte Aufgaben. Sonderreinigungen werden für besondere Verschmutzungen, Anlässe oder Materialien separat geplant.')]),
'wachschutz':('Sicherheitsleistungen mit klaren Zuständigkeiten',[('Objekt- & Werkschutz','Zutritte, Nutzungszeiten und besonders sensible Bereiche werden als Grundlage des Schutzkonzepts erfasst.'),('Revier- & Schließdienste','Kontrollpunkte und Schließaufgaben werden mit Meldewegen und Zuständigkeiten verbunden.'),('Empfang & Besucherservice','Besucherabläufe und interne Ansprechpartner helfen, die Aufgabe am Empfang klar zu definieren.')],[('Wer übernimmt den Sicherheitsdienst?','COMPAKT stimmt Sicherheitsanfragen mit der WSG innerhalb der FORM Gruppe ab. Die Zuständigkeiten werden für das jeweilige Objekt geklärt.'),('Welche Informationen braucht ein Schutzkonzept?','Wichtig sind Objektgröße, Nutzung, Zugänge, Betriebszeiten und die gewünschten Kontroll- oder Präsenzaufgaben. Vorhandene Sicherheitsregelungen sollten ebenfalls benannt werden.')]),
'winterdienst':('Vorbereitet, bevor es glatt wird',[('Flächenplan','Gehwege, Eingänge, Zufahrten und weitere beauftragte Bereiche werden eindeutig zugeordnet.'),('Zugänglichkeit','Tore, abgestellte Fahrzeuge und mögliche Baustellen werden in der Einsatzvorbereitung berücksichtigt.'),('Abstimmung','Ansprechpartner, vereinbarte Aufgaben und Änderungen an den Flächen werden vorab geklärt.')],[('Wann sollte ich Winterdienst anfragen?','Am besten vor Beginn der Wintersaison, damit Flächen und Einsatzmöglichkeiten rechtzeitig geklärt werden können. Kurzfristige Anfragen werden nach Verfügbarkeit geprüft.'),('Welche Flächen gehören zum Auftrag?','Ausschließlich die vereinbarten Flächen. Ein Lageplan hilft, Räumbereiche, Zugänge und Besonderheiten eindeutig zu erfassen.')]),
'grafittientfernung':('Die Oberfläche entscheidet über das Verfahren',[('Untergrund erfassen','Putz, Klinker, Naturstein oder Metall: Material und Zustand bilden die Grundlage der Planung.'),('Verschmutzung prüfen','Art und Alter der Farbe sowie frühere Behandlungen können das Ergebnis beeinflussen.'),('Schutz mitdenken','Nach der Entfernung kann geprüft werden, ob ein geeignetes Schutzsystem für spätere Reinigungen sinnvoll ist.')],[('Kann jedes Graffiti vollständig entfernt werden?','Das lässt sich nicht pauschal zusagen. Untergrund, Eindringtiefe und vorhandene Schäden beeinflussen das Ergebnis; gegebenenfalls hilft eine Probefläche.'),('Reicht ein Foto für die Anfrage?','Fotos sind ein guter Anfang. Hilfreich sind außerdem Adresse, ungefähre Fläche und Informationen zum Material. Ob eine Besichtigung nötig ist, wird anschließend geklärt.')]),
'hausmeister':('Regelmäßige Präsenz für Ihr Gebäude',[('Objektbegehung','Vereinbarte Bereiche kontrollieren, Auffälligkeiten aufnehmen und an die zuständigen Ansprechpartner weitergeben.'),('Alltagsaufgaben','Mülltonnenbereitstellung und weitere wiederkehrende Aufgaben werden in einem festen Umfang organisiert.'),('Arbeiten koordinieren','Für fachpflichtige Arbeiten werden entsprechend qualifizierte Unternehmen eingebunden.')],[('Gehören alle Reparaturen zum Hausmeisterdienst?','Nein. Vereinbarte Kleinreparaturen werden von fachpflichtigen Arbeiten unterschieden. Umfang und Zuständigkeiten werden vorab geklärt.'),('Lässt sich der Hausmeisterdienst mit Reinigung verbinden?','Ja. Treppenhausreinigung, Außenpflege und Winterdienst können gemeinsam abgestimmt werden, damit die Betreuung organisatorisch zusammenpasst.')]),
'gruenflaechenpflege':('Außenanlagen über das Jahr begleiten',[('Rasen & Beete','Flächen, Pflegezustand und gewünschtes Erscheinungsbild werden bei der Planung berücksichtigt.'),('Hecken & Sträucher','Schnittbedarf und geeignete Zeitpunkte werden objektbezogen abgestimmt.'),('Wege & Laub','Auch befestigte Flächen und saisonaler Laubanfall können zum Pflegeplan gehören.')],[('Kann ich eine einmalige Pflege anfragen?','Ja. Nennen Sie uns den Zustand der Fläche und die gewünschten Arbeiten. Regelmäßige und einmalige Aufgaben werden gesondert abgestimmt.'),('Ist die Entsorgung von Grünschnitt enthalten?','Das wird im Angebot festgelegt. Bitte geben Sie an, welche Mengen zu erwarten sind und welche Möglichkeiten zur Aufnahme oder Abfuhr bestehen.')]),
'immobilienservice':('Ein Objekt. Zusammenhängende Aufgaben.',[('Innenbereiche','Reinigung und Betreuung gemeinschaftlich genutzter Flächen werden nach Nutzung und Bedarf organisiert.'),('Außenbereiche','Grünpflege, Wege und saisonale Aufgaben lassen sich in ein abgestimmtes Konzept einbinden.'),('Koordination','Zuständigkeiten zwischen Eigentümern, Verwaltung und beteiligten Dienstleistern werden klar zugeordnet.')],[('Ist Immobilienservice dasselbe wie Hausverwaltung?','Die hier angebotene Objektbetreuung umfasst praktische Dienstleistungen und deren Abstimmung. Eine vollständige kaufmännische Hausverwaltung ist damit nicht automatisch vereinbart.'),('Können bestehende Dienstleister weiter eingebunden bleiben?','Das kann bei der Planung besprochen werden. Wichtig sind eindeutig abgegrenzte Aufgaben und ein gemeinsames Verständnis der Zuständigkeiten.')]),
'entlastungsbetrag':('Alltagshilfe nach persönlichem Bedarf',[('Haushalt','Welche Aufgaben im Haushalt übernommen werden sollen, wird gemeinsam festgelegt.'),('Besorgungen','Unterstützungsbedarf bei Einkäufen und alltäglichen Wegen wird persönlich besprochen.'),('Organisation','Umfang, Termine und verfügbare Leistungen werden vor Beginn abgestimmt.')],[('Kann ich Alltagshilfe auch privat anfragen?','Sprechen Sie uns mit Ihrem gewünschten Umfang an. Verfügbarkeit, Kosten und Abrechnung werden vor dem Einsatz persönlich geklärt.'),('Werden alle Aufgaben über die Pflegekasse erstattet?','Nein. Die Erstattungsfähigkeit muss für das konkrete Angebot vorab geklärt werden. Stimmen Sie die Kostenübernahme mit Ihrer Pflegekasse ab.')]),
'drohnenservice':('Technik gezielt für Ihr Objekt einsetzen',[('Reinigung','Für geeignete Flächen wird geprüft, ob Drohnentechnik eine passende Ausführung ermöglicht.'),('Sichtprüfung','Bildaufnahmen können helfen, schwer zugängliche Bereiche zu dokumentieren und Auffälligkeiten zu erkennen.'),('Einsatzplanung','Umfeld, Zugang, Witterung und notwendige Freigaben werden vorab betrachtet.')],[('Kann jede Fassade mit einer Drohne gereinigt werden?','Nein. Material, Gebäudegeometrie, Umgebung und Einsatzbedingungen müssen geeignet sein. Das Vorgehen wird zusammen mit dem FORM Drohnenservice geprüft.'),('Ersetzt eine Drohnenaufnahme ein technisches Gutachten?','Eine visuelle Dokumentation kann Hinweise geben. Sie ersetzt nicht automatisch eine fachliche Begutachtung oder eine weiterführende technische Prüfung.')])}

